import { tags } from "typia";

/**
 * Aggregated refund-related metrics for a dashboard period.
 *
 * This type summarizes core refund KPIs derived from one or more rows of the
 * `shopping_mall_refund_and_dispute_stats` snapshot model and, optionally,
 * complementary live data from refund request and payment refund tables.
 *
 * It is optimized for rendering concise numerical widgets and trend indicators
 * in administrative dashboards.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallRefundsSummary = {
  /**
   * Total number of refund requests created within the dashboard period.
   *
   * The value is sourced from `refund_request_count` in one or more
   * `shopping_mall_refund_and_dispute_stats` rows corresponding to the
   * selected dates.
   */
  refund_request_count: number & tags.Type<"int32">;

  /**
   * Total number of refund requests approved within the dashboard period.
   *
   * This figure counts approvals that occurred in the window, regardless of
   * when the underlying requests were created, and mirrors
   * `approved_refund_request_count` from the snapshot model.
   */
  approved_refund_request_count: number & tags.Type<"int32">;

  /**
   * Total number of refund requests rejected within the dashboard period.
   *
   * It provides insight into decision patterns and aligns with
   * `rejected_refund_request_count` in the snapshot table.
   */
  rejected_refund_request_count: number & tags.Type<"int32">;

  /**
   * Total monetary amount refunded during the dashboard period in the
   * platform base currency.
   *
   * This value aggregates the `refunded_amount` field across relevant
   * `shopping_mall_refund_and_dispute_stats` rows and may combine multiple
   * currencies normalized to the platform base, depending on analytics
   * implementation.
   */
  refunded_amount: number;

  /**
   * Number of refund operations during the dashboard period that were partial
   * relative to the original order or item amount.
   *
   * The metric helps identify whether refunds are typically full or partial
   * and is taken from `partial_refund_count` in the snapshot model.
   */
  partial_refund_count: number & tags.Type<"int32">;

  /**
   * Number of refund operations during the dashboard period that fully
   * refunded the relevant items or orders.
   *
   * Together with `partial_refund_count`, this field gives a quick overview
   * of how complete or partial typical refunds are.
   */
  full_refund_count: number & tags.Type<"int32">;

  /**
   * Average time in hours between refund request creation and final decision
   * for cases resolved within the dashboard period.
   *
   * It mirrors `average_refund_resolution_time_hours` in
   * `shopping_mall_refund_and_dispute_stats` and is used to monitor
   * operational efficiency and SLA adherence for refund processing.
   */
  average_refund_resolution_time_hours: number;
};
